function pageContent(def) {
  if (def.slug === "home") return homeContent();
  const content = [hero(`${def.slug}-hero`, ...def.hero, def.family)];
  for (const [idx, s] of (def.sections || []).entries()) content.push(section(`${def.slug}-sec-${idx}`, s[0], s[1], s[2]?.length ? [cards(`${def.slug}-cards-${idx}`, s[2].map(x => ({ title:x[0], text:x[1], meta:x[2] })))] : [], idx + 1));
  if (def.shortcode) content.push(section(`${def.slug}-plugin`, "بخش متصل به وردپرس", "داده زنده این قسمت توسط افزونه مربوط بارگذاری می‌شود.", [pluginMount(`${def.slug}-mount`, "محتوای زنده", "اگر این بخش خالی است، افزونه و داده نمونه را بررسی کنید.", def.shortcode)], 3));
  if (def.elementorSearch) content.push(section(`${def.slug}-plugin`, "جست‌وجوی سایت", "این فرم از widget جست‌وجوی Elementor Pro استفاده می‌کند و به افزونه جست‌وجوی جانبی وابسته نیست.", [searchWidget(`${def.slug}-search`)], 3));
  if (def.elementorPosts) content.push(section(`${def.slug}-plugin`, "تازه‌ترین نوشته‌ها", "فهرست نوشته‌ها با لوپ اختصاصی و Dynamic Grid المنت پک پرو بارگذاری می‌شود.", [dynamicGrid(`${def.slug}-posts`, emittedIds["loop-post"], "az-post-grid")], 3));
  if (["student-works", "gallery"].includes(def.slug)) content.push(section(`${def.slug}-dynamic`, "آرشیو زنده آثار", "آثار تازه با لوپ اختصاصی Element Pack Pro نمایش داده می‌شوند.", [dynamicGrid(`${def.slug}-works`, emittedIds["loop-artwork"], "az-work-grid")], 2));
  if (def.slug === "contact") content.push(section(`${def.slug}-live`, "پیام و مسیر کارگاه", "فرم حرفه‌ای Elementor Pro در کنار نقشه نشان؛ کلید API نقشه را پس از درون‌ریزی وارد کنید.", [container(`${def.slug}-live-grid`, [formWidget(`${def.slug}-form`), neshanMap(`${def.slug}-map`)], "az-contact-live", {flex_direction:"row"})], 3));
  content.push(section(`${def.slug}-state`, "وضعیت‌های رابط", "ساختار پایدار برای بارگذاری، نبود داده و خطا.", [cards(`${def.slug}-states`, [{title:"در حال بارگذاری",text:"اسکلت محتوا بدون جابه‌جایی چیدمان.",meta:"loading"},{title:"هنوز داده‌ای نیست",text:"اقدام بعدی متناسب با این صفحه نمایش داده می‌شود.",meta:"empty"},{title:"بارگذاری انجام نشد",text:"پیام روشن همراه با امکان تلاش دوباره.",meta:"error"}]) ], 2));
  return [container(`${def.slug}-root`, content, `az-page az-page--${def.family}`)];
}
function dynamicContent(def) {
  const dynamicWidgets = [dynamicContentWidget(`${def.slug}-content`)];
  if (def.integration === "learndash-course") dynamicWidgets.push(shortcode(`${def.slug}-course-content`, "[course_content]"));
  if (def.integration === "learndash-progress") dynamicWidgets.unshift(shortcode(`${def.slug}-progress`, "[learndash_course_progress]"));
  if (def.integration === "woocommerce") dynamicWidgets.splice(0, dynamicWidgets.length,
    wooWidget(`${def.slug}-images`, "woocommerce-product-images"),
    wooWidget(`${def.slug}-price`, "woocommerce-product-price"),
    wooWidget(`${def.slug}-cart`, "woocommerce-product-add-to-cart"),
    wooWidget(`${def.slug}-tabs`, "woocommerce-product-data-tabs"),
    wooWidget(`${def.slug}-related`, "woocommerce-product-related")
  );
  const main = container(`${def.slug}-main`, [text(`${def.slug}-label`, def.heading, "az-meta"), dynamicTitle(`${def.slug}-title`), ...dynamicWidgets], "az-block");
  const aside = container(`${def.slug}-aside`, [heading(`${def.slug}-aside-h`, "اطلاعات و اقدام", "h3"), iconList(`${def.slug}-list`, ["وضعیت دسترسی", "جزئیات و پیش‌نیاز", "پشتیبانی کارگاه"]), button(`${def.slug}-button`, "ادامه / ثبت‌نام")], "az-single__aside az-panel");
  return [container(`${def.slug}-root`, [container(`${def.slug}-layout`, [main, aside], "az-section az-single", {flex_direction:"row"})], "az-page")];
}
