function doc(content, templateType = "single-page") {
  return { content, settings: { template:"elementor_canvas", custom_css:CSS, background_background:"classic", background_color:C.bg }, metadata: { template_type:templateType, include_in_zip:1, elementor_pro_required:1, wp_page_template:"elementor_canvas" } };
}

