const manifestTemplates = {};
let numericId = 1001;
async function emit(slug, title, type, location, content, templateType = "single-page") {
  const current = String(numericId++);
  emittedIds[slug] = current;
  await writeFile(path.join(templatesDir, `${current}.json`), JSON.stringify(doc(content, templateType)));
  await writeFile(path.join(directDir, `${slug}.json`), JSON.stringify({ version:"0.4", title, type:type === "page" ? "page" : type, content, page_settings:{ template:"elementor_canvas", custom_css:CSS } }));
  manifestTemplates[current] = { title, doc_type:type, thumbnail:false, location };
}

